import {
  type ColumnDef,
  flexRender,
  getCoreRowModel,
  getSortedRowModel,
  type SortingState,
  useReactTable,
} from "@tanstack/react-table";
import { useVirtualizer } from "@tanstack/react-virtual";
import { useRef, useState } from "react";

export function DataTable<T>({
  data,
  columns,
  onSelect,
  label,
}: {
  data: T[];
  columns: ColumnDef<T>[];
  onSelect?: (row: T) => void;
  label: string;
}) {
  const [sorting, setSorting] = useState<SortingState>([]);
  const parent = useRef<HTMLDivElement>(null);
  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  });
  const rows = table.getRowModel().rows;
  const virtual = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parent.current,
    estimateSize: () => 32,
    overscan: 8,
  });
  const width = `repeat(${columns.length}, minmax(90px, 1fr))`;
  return (
    <div className="table" role="table" aria-label={label}>
      <div role="rowgroup">
        {table.getHeaderGroups().map((group) => (
          <div
            className="table-row table-head"
            role="row"
            key={group.id}
            style={{ gridTemplateColumns: width }}
          >
            {group.headers.map((header) => (
              <div role="columnheader" key={header.id}>
                <button
                  type="button"
                  onClick={header.column.getToggleSortingHandler()}
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                  {header.column.getIsSorted() === "asc"
                    ? " ↑"
                    : header.column.getIsSorted() === "desc"
                      ? " ↓"
                      : ""}
                </button>
              </div>
            ))}
          </div>
        ))}
      </div>
      <div className="table-scroll" ref={parent} role="rowgroup">
        <div style={{ height: virtual.getTotalSize(), position: "relative" }}>
          {virtual.getVirtualItems().map((item) => {
            const row = rows[item.index];
            if (!row) return null;
            return (
              <div
                role="row"
                key={row.id}
                className={`table-row ${onSelect ? "selectable" : ""}`}
                style={{
                  position: "absolute",
                  top: 0,
                  transform: `translateY(${item.start}px)`,
                  height: item.size,
                  width: "100%",
                  gridTemplateColumns: width,
                }}
              >
                {row.getVisibleCells().map((cell, index) => (
                  <div
                    role="cell"
                    key={cell.id}
                    title={String(cell.getValue() ?? "")}
                  >
                    {onSelect && index === 0 ? (
                      <button
                        type="button"
                        onClick={() => onSelect(row.original)}
                      >
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </button>
                    ) : (
                      flexRender(cell.column.columnDef.cell, cell.getContext())
                    )}
                  </div>
                ))}
              </div>
            );
          })}
        </div>
        {!rows.length && <p className="empty">No rows to display</p>}
      </div>
    </div>
  );
}
export function columnsFor<T>(fields: [keyof T, string][]): ColumnDef<T>[] {
  return fields.map(([key, label]) => ({
    accessorKey: String(key),
    header: label,
    cell: (info) => {
      const value = info.getValue();
      return Array.isArray(value)
        ? value.join(", ")
        : value === null
          ? "—"
          : String(value);
    },
  }));
}

