  useReactTable,
} from "@tanstack/react-table";
import { useVirtualizer } from "@tanstack/react-virtual";
import { useRef, useState } from "react";

export function DataTable<T>({
  data,
  columns,
  onSelect,
  label,
}: {
  data: T[];
  columns: ColumnDef<T>[];
  onSelect?: (row: T) => void;
  label: string;
}) {
  const [sorting, setSorting] = useState<SortingState>([]);
  const parent = useRef<HTMLDivElement>(null);
  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  });
  const rows = table.getRowModel().rows;
  const virtual = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parent.current,
    estimateSize: () => 32,
    overscan: 8,
  });
  const width = `repeat(${columns.length}, minmax(90px, 1fr))`;
  return (
    <div className="table" role="table" aria-label={label}>
      <div role="rowgroup">
        {table.getHeaderGroups().map((group) => (
          <div
            className="table-row table-head"
            role="row"
            key={group.id}
            style={{ gridTemplateColumns: width }}
          >
            {group.headers.map((header) => (
              <div role="columnheader" key={header.id}>
                <button
                  type="button"
                  onClick={header.column.getToggleSortingHandler()}
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                  {header.column.getIsSorted() === "asc"
                    ? " ↑"
                    : header.column.getIsSorted() === "desc"
                      ? " ↓"
                      : ""}
                </button>
              </div>
            ))}
          </div>
        ))}
      </div>
      <div className="table-scroll" ref={parent} role="rowgroup">
        <div style={{ height: virtual.getTotalSize(), position: "relative" }}>
          {virtual.getVirtualItems().map((item) => {
            const row = rows[item.index];
            if (!row) return null;
            return (
              <div
                role="row"
                key={row.id}
                className={`table-row ${onSelect ? "selectable" : ""}`}
                style={{
                  position: "absolute",
                  top: 0,
                  transform: `translateY(${item.start}px)`,
                  height: item.size,
                  width: "100%",
                  gridTemplateColumns: width,
                }}
              >
                {row.getVisibleCells().map((cell, index) => (
                  <div
                    role="cell"
                    key={cell.id}
                    title={String(cell.getValue() ?? "")}
                  >
                    {onSelect && index === 0 ? (
                      <button
                        type="button"
                        onClick={() => onSelect(row.original)}
                      >
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </button>
                    ) : (
                      flexRender(cell.column.columnDef.cell, cell.getContext())
                    )}
                  </div>
                ))}
              </div>
            );
          })}
        </div>
        {!rows.length && <p className="empty">No rows to display</p>}
      </div>
    </div>
  );
}
export function columnsFor<T>(fields: [keyof T, string][]): ColumnDef<T>[] {
  return fields.map(([key, label]) => ({
    accessorKey: String(key),
    header: label,
    cell: (info) => {
      const value = info.getValue();
      return Array.isArray(value)
        ? value.join(", ")
        : value === null
          ? "—"
          : String(value);
    },
  }));
}

import { useEffect, useState } from "react";
import { Confirmation, ErrorBanner, Field } from "../../components/Primitives";
import { command, errorMessage } from "../../ipc/client";
import type { Profile, SaveProfile } from "../../ipc/types";
import { parseProperties, validateProfile } from "./validation";

const fresh = (): Profile => ({
  id: crypto.randomUUID(),
  name: "",
  bootstrapServers: ["localhost:9092"],
  clientId: null,
  securityProtocol: "PLAINTEXT",
  sasl: null,
  tls: null,
  extraProperties: {},
});
export function Connections({
  onConnect,
  active,
}: {
  onConnect: (id: string) => Promise<void>;
  active: string | null;
}) {
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [profile, setProfile] = useState(fresh);
  const [password, setPassword] = useState("");
  const [keyPassword, setKeyPassword] = useState("");
  const [storePassword, setStorePassword] = useState("");
  const [properties, setProperties] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [busy, setBusy] = useState(false);
  const [remove, setRemove] = useState<Profile | null>(null);
  const reload = () =>
    command("get_profiles")
      .then(setProfiles)
      .catch((e) => setError(errorMessage(e)));
  useEffect(() => {
    void reload();
  }, []);
  const clearSecrets = () => {
    setPassword("");
    setKeyPassword("");
    setStorePassword("");
  };
  const edit = (p: Profile) => {
    clearSecrets();
    setProfile(structuredClone(p));
    setProperties(
      Object.entries(p.extraProperties)
        .map(([k, v]) => `${k}=${v}`)
        .join("\n"),
    );
    setNotice("");
    setError("");
  };
  const request = (): SaveProfile => ({
    profile: { ...profile, extraProperties: parseProperties(properties) },
    secrets: {
      ...(password ? { "sasl-password": password } : {}),
      ...(keyPassword ? { "key-password": keyPassword } : {}),
      ...(storePassword ? { "keystore-password": storePassword } : {}),
    },
  });
  const action = async (save: boolean) => {
    setError("");
    setNotice("");
    const invalid = validateProfile(profile);
    if (invalid) {
      setError(invalid);
      return;
    }
    setBusy(true);
    try {
      if (save) {
        const result = await command("save_profile", { request: request() });
        setProfile(result.profile);
        clearSecrets();
        setNotice(result.warnings.join(" ") || "Profile saved.");
        await reload();
      } else {
        const result = await command("test_connection", { request: request() });
        setNotice(
          `Connected to ${result.clusterId ?? "cluster"}: ${result.brokers.length} brokers.`,
        );
      }
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  };
  const tls = profile.tls ?? {
    caPath: null,
    certificatePath: null,
    privateKeyPath: null,
    pkcs12Path: null,
    keyPasswordRef: null,
    keystorePasswordRef: null,
  };
  const choose = async (
    field: "caPath" | "certificatePath" | "privateKeyPath" | "pkcs12Path",
  ) => {
    try {
      const path = await command("choose_certificate");
      if (path) setProfile({ ...profile, tls: { ...tls, [field]: path } });
    } catch (e) {
      setError(errorMessage(e));
    }
  };
  return (
    <div className="split">
      <aside className="resource-list">
        <div className="toolbar">
          <h2>Connections</h2>
          <button
            type="button"
            onClick={() => {
              edit(fresh());
            }}
          >
            New
          </button>
        </div>
        {profiles.map((p) => (
          <div className="profile-row" key={p.id}>
            <button type="button" onClick={() => edit(p)}>
              {p.name}
              {active === p.id ? " ●" : ""}
            </button>
            <button
              type="button"
              disabled={busy}
              onClick={() => {
                setBusy(true);
                void onConnect(p.id)
                  .catch((e) => setError(errorMessage(e)))
                  .finally(() => setBusy(false));
              }}
            >
              Connect
            </button>
            <button
              type="button"
              aria-label={`Delete ${p.name}`}
              onClick={() => setRemove(p)}
            >
              ×
            </button>
          </div>
        ))}
      </aside>
      <section className="editor">
        <h2>Connection profile</h2>
        <ErrorBanner message={error} />
        {notice && <p role="status">{notice}</p>}
        <Field label="Name">
          <input
            aria-label="Name"
            value={profile.name}
            onChange={(e) => setProfile({ ...profile, name: e.target.value })}
          />
        </Field>
        <Field label="Bootstrap servers">
          <input
            aria-label="Bootstrap servers"
            value={profile.bootstrapServers.join(", ")}
            onChange={(e) =>
              setProfile({
                ...profile,
                bootstrapServers: e.target.value
                  .split(",")
                  .map((s) => s.trim()),
              })
            }
          />
        </Field>
        <Field label="Client ID">
          <input
            aria-label="Client ID"
            value={profile.clientId ?? ""}
            onChange={(e) =>
              setProfile({ ...profile, clientId: e.target.value || null })
            }
          />
        </Field>
        <Field label="Security protocol">
          <select
            aria-label="Security protocol"
            value={profile.securityProtocol}
            onChange={(e) =>
              setProfile({
                ...profile,
                securityProtocol: e.target.value,
                sasl: e.target.value.startsWith("SASL")
                  ? (profile.sasl ?? {
                      mechanism: "PLAIN",
                      username: "",
                      passwordRef: null,
                    })
                  : null,
                tls: e.target.value.endsWith("SSL") ? tls : null,
              })
            }
          >
            {["PLAINTEXT", "SSL", "SASL_PLAINTEXT", "SASL_SSL"].map((p) => (
              <option key={p}>{p}</option>
            ))}
          </select>
        </Field>
        {profile.sasl && (
          <>
            <Field label="SASL mechanism">
              <select
                aria-label="SASL mechanism"
                value={profile.sasl.mechanism}
                onChange={(e) =>
                  setProfile({
                    ...profile,
                    sasl: { ...profile.sasl!, mechanism: e.target.value },
                  })
                }
              >
                {["PLAIN", "SCRAM-SHA-256", "SCRAM-SHA-512"].map((p) => (
                  <option key={p}>{p}</option>
                ))}
              </select>
            </Field>
            <Field label="Username">
              <input
                aria-label="Username"
                value={profile.sasl.username}
                onChange={(e) =>
                  setProfile({
                    ...profile,
                    sasl: { ...profile.sasl!, username: e.target.value },
                  })
                }
              />
            </Field>
            <Field label="Password">
              <input
                aria-label="Password"
                type="password"
                autoComplete="off"
                placeholder={
                  profile.sasl.passwordRef
                    ? "Saved credential; leave blank to keep"
                    : ""
                }
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </Field>
          </>
        )}
        {profile.securityProtocol.endsWith("SSL") && (
          <>
            <p className="muted">
              Hostname verification is enabled. Leave CA blank to use system
              trust.
            </p>
            {(
              [
                ["caPath", "CA (PEM)"],
                ["certificatePath", "Client certificate (PEM)"],
                ["privateKeyPath", "Private key (PEM)"],
                ["pkcs12Path", "Keystore (PKCS#12)"],
              ] as const
            ).map(([key, label]) => (
              <Field label={label} key={key}>
                <div className="toolbar">
                  <input
                    aria-label={label}
                    value={tls[key] ?? ""}
                    onChange={(e) =>
                      setProfile({
                        ...profile,
                        tls: { ...tls, [key]: e.target.value || null },
                      })
                    }
                  />
                  <button type="button" onClick={() => void choose(key)}>
                    Choose
                  </button>
                </div>
              </Field>
            ))}
            <Field label="Private key password">
              <input
                aria-label="Private key password"
                type="password"
                autoComplete="off"
                value={keyPassword}
                onChange={(e) => setKeyPassword(e.target.value)}
              />
            </Field>
            <Field label="Keystore password">
              <input
                aria-label="Keystore password"
                type="password"
                autoComplete="off"
                value={storePassword}
                onChange={(e) => setStorePassword(e.target.value)}
              />
            </Field>
          </>
        )}
        <Field label="Extra safe properties">
          <textarea
            aria-label="Extra safe properties"
            value={properties}
            onChange={(e) => setProperties(e.target.value)}
            placeholder="socket.timeout.ms=10000"
          />
        </Field>
        <div className="toolbar">
          <button
            type="button"
            disabled={busy}
            onClick={() => void action(false)}
          >
            Test connection
          </button>
          <button
            type="button"
            className="primary"
            disabled={busy}
            onClick={() => void action(true)}
          >
            Save
          </button>
          <button
            type="button"
            onClick={() => {
              edit(fresh());
            }}
          >
            Cancel
          </button>
        </div>
      </section>
      {remove && (
        <Confirmation
          title="Delete connection profile"
          onCancel={() => setRemove(null)}
          busy={busy}
          onConfirm={() => {
            setBusy(true);
            void command("delete_profile", { id: remove.id })
              .then(() => {
                setRemove(null);
                void reload();
              })
              .catch((e) => setError(errorMessage(e)))
              .finally(() => setBusy(false));
          }}
        >
          <p>Delete {remove.name} and its saved credentials?</p>
        </Confirmation>
      )}
    </div>
  );
}

