const topicColumns = columnsFor<Topic>([
  ["name", "Topic"],
  ["partitions", "Partitions"],
  ["internal", "Internal"],
]);
const partitionColumns = columnsFor<Partition>([
  ["id", "Partition"],
  ["leader", "Leader"],
  ["replicas", "Replicas"],
  ["isr", "ISR"],
  ["earliestOffset", "Earliest"],
  ["latestOffset", "Latest"],
]);
const configColumns = columnsFor<ConfigEntry>([
  ["name", "Parameter"],
  ["value", "Value"],
  ["isDefault", "Default"],
  ["readOnly", "Read only"],
  ["sensitive", "Sensitive"],
]);
export function filterTopics(
  topics: Topic[],
  query: string,
  internal: boolean,
): Topic[] {
  return topics.filter(
    (t) =>
      (internal || !t.internal) &&
      t.name.toLowerCase().includes(query.toLowerCase()),
  );
}
export function Topics({ onOpen }: { onOpen: (topic: string) => void }) {
  const [topics, setTopics] = useState<Topic[]>([]);
  const [query, setQuery] = useState("");
  const [internal, setInternal] = useState(false);
  const [error, setError] = useState("");
  const [creating, setCreating] = useState(false);
  const [busy, setBusy] = useState(false);
  const [name, setName] = useState("");
  const [partitions, setPartitions] = useState(1);
  const [replication, setReplication] = useState(1);
  const [config, setConfig] = useState("");
  const refresh = () => {
    setBusy(true);
    return command("list_topics")
      .then(setTopics)
      .catch((e) => setError(errorMessage(e)))
      .finally(() => setBusy(false));
  };
  useEffect(() => {
    void refresh();
  }, []);
  const create = async () => {
    setError("");
    if (
      !/^[a-zA-Z0-9._-]{1,249}$/.test(name) ||
      name === "." ||
      name === ".." ||
      partitions < 1 ||
      replication < 1
    ) {
      setError(
        "Enter a valid topic name and positive partition / replication counts.",
      );
      return;
    }
    setBusy(true);
    try {
